    INSERT INTO `tmp_fproj009_sample_2` (`id`, `code`, `name`, `status`, `match_priority`, `description`, `system_reserved`, `version`, `tenant_id`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `deleted_time`) VALUES
        (993009000005, 'FPROJ009_SAMPLE_DS_ENG', '直签-工程类【结构草稿】', 'DRAFT', 10, '配置结构示例，生产需绑定Owner；TASK_NATIVE/STAGE_NATIVE仅示范原生配置，不代表领域业务已实现。DRAFT未开运行、不进入匹配候选；仅供浏览、复制。初验/终验、审批、归档与闭环均为待办理配置，不创建实体或完成事实。含启动会；初验、初验后满意度及终验配置；实施方式未限定（部分限定示例）。matchPriority=10，小值优先仅为草稿属性说明；与售前空维草稿潜在重叠不构成匹配候选或预演通过。CRM重大级别不预置。', b'0', 0, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-samples-20260909', '2026-09-09 00:00:00', b'0', NULL),
        (993009000347, 'FPROJ009_SAMPLE_DS_GEN', '直签-普通类【结构草稿】', 'DRAFT', 20, '配置结构示例，生产需绑定Owner；TASK_NATIVE/STAGE_NATIVE仅示范原生配置，不代表领域业务已实现。DRAFT未开运行、不进入匹配候选；仅供浏览、复制。初验/终验、审批、归档与闭环均为待办理配置，不创建实体或完成事实。无工程启动会；保留初验、初验后满意度及终验配置；三项受控维度精确限定。matchPriority=20，小值优先仅为草稿属性说明；与售前空维草稿潜在重叠不构成匹配候选或预演通过。CRM重大级别不预置。', b'0', 0, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-samples-20260909', '2026-09-09 00:00:00', b'0', NULL),
        (993009000662, 'FPROJ009_SAMPLE_CH_ENG', '非直签-工程类【结构草稿】', 'DRAFT', 30, '配置结构示例，生产需绑定Owner；TASK_NATIVE/STAGE_NATIVE仅示范原生配置，不代表领域业务已实现。DRAFT未开运行、不进入匹配候选；仅供浏览、复制。初验/终验、审批、归档与闭环均为待办理配置，不创建实体或完成事实。含启动会和现场验货单；不设初验，仅终验及验收阶段满意度；实施方式未限定。matchPriority=30，小值优先仅为草稿属性说明；与售前空维草稿潜在重叠不构成匹配候选或预演通过。CRM重大级别不预置。', b'0', 0, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-samples-20260909', '2026-09-09 00:00:00', b'0', NULL),
        (993009000986, 'FPROJ009_SAMPLE_CH_DIR', '非直签-普通类（原厂直服）【结构草稿】', 'DRAFT', 40, '配置结构示例，生产需绑定Owner；TASK_NATIVE/STAGE_NATIVE仅示范原生配置，不代表领域业务已实现。DRAFT未开运行、不进入匹配候选；仅供浏览、复制。初验/终验、审批、归档与闭环均为待办理配置，不创建实体或完成事实。无启动会和初验；现场验货单、终验及验收阶段满意度配置。matchPriority=40，小值优先仅为草稿属性说明；与售前空维草稿潜在重叠不构成匹配候选或预演通过。CRM重大级别不预置。', b'0', 0, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-samples-20260909', '2026-09-09 00:00:00', b'0', NULL),
        (993009001292, 'FPROJ009_SAMPLE_CH_SUP', '非直签-普通类（原厂督导）【结构草稿】', 'DRAFT', 50, '配置结构示例，生产需绑定Owner；TASK_NATIVE/STAGE_NATIVE仅示范原生配置，不代表领域业务已实现。DRAFT未开运行、不进入匹配候选；仅供浏览、复制。初验/终验、审批、归档与闭环均为待办理配置，不创建实体或完成事实。无启动会和初验；督导渠道实施，核心交付件为现场服务单，配置终验。matchPriority=50，小值优先仅为草稿属性说明；与售前空维草稿潜在重叠不构成匹配候选或预演通过。CRM重大级别不预置。', b'0', 0, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-samples-20260909', '2026-09-09 00:00:00', b'0', NULL),
        (993009001589, 'FPROJ009_SAMPLE_PRE', '售前测试场景（显式选择）【结构草稿】', 'DRAFT', 90, '配置结构示例，生产需绑定Owner；TASK_NATIVE/STAGE_NATIVE仅示范原生配置，不代表领域业务已实现。DRAFT未开运行、不进入匹配候选；仅供浏览、复制。初验/终验、审批、归档与闭环均为待办理配置，不创建实体或完成事实。显式选择的场景草稿，四维不能单独识别售前；仅S0→S4，S4仅EXE-03/04。可从S4按CLO契约申请闭环，不补S5/S6；转销关联待领域Owner办理。matchPriority=90，小值优先仅为草稿属性说明；与售前空维草稿潜在重叠不构成匹配候选或预演通过。CRM重大级别不预置。', b'0', 0, 1, 'fproj009-samples-20260909', '2026-09-09 00:00:00', 'fproj009-samples-20260909', '2026-09-09 00:00:00', b'0', NULL);
